"use strict";

angular
	.module("irtech.netcity.school.refbook")
	.controller("EditRefItemCtrl", ($scope, refBookRepository, refType, refItem, $uibModalInstance) => {

		if (refItem.id) {
			$scope.header = language.Generic.SetupSchool.kPageTitle_Edit + " \"" + refType.name + "\"";
		} else {
			$scope.header = language.Generic.SetupSchool.kPageTitle_New + " \"" + refType.name + "\"";
		}
		
		$.extend($scope, {
			language: language,
			data : {
				refType: refType,
				refItem: refItem
			}
		});

		$scope.save = () => {
			if (!$scope.data.refItem.name.trim()) {
				alert("Необходимо заполнить полное название");
				return;
			}
			refBookRepository.saveRefItems(refType.refType, $scope.data.refItem, refType.parameterId)
				.then((item) => {
					if (!item) {
						return;
					}
					$uibModalInstance.close(refItem);
				});
		}

		$scope.cancel = () => {
			$uibModalInstance.dismiss('cancel');
		}
	});



