const module = angular.module("irtech.netcity.school.refbook",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "netcity.common.menu", "irtech.netcity.ui-components"
	]);

require("./repository.js");
require("./list/refbookCtrl.js");
require("./edit/editRefItemCtrl.js");
 
module.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/list/", {
			templateUrl: "/static/dist/app/school/refbook/list/template.html",
			controller: "RefBookCtrl"
		})
		.when("/edit/", {
			templateUrl: "/static/dist/app/school/refbook/edit/template.html",
			controller: "EditRefItemCtrl"
		})
		.otherwise({
			templateUrl: "/static/dist/app/school/refbook/list/template.html",
			controller: "RefBookCtrl"
		});
	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});


