"use strict";

angular
	.module("irtech.netcity.school.refbook")
	.controller("RefBookCtrl", ($scope, $http, $document, $location, $appLoader, refBookRepository, $uibModal, $alerts) => {

		$scope.$parent.page = {
			title: language.Generic.SetupSchool.kTitleRefBooks
		};

		$.extend($scope, {
			language: language,
			state: {
				dataReady: false,
				emptyData: false
			},
			data: {
				refType: null,
				checked: [],
				refTypes: [],
				refItems: []
			}
		});

		const typesReady = refBookRepository.getRefs().then((refTypes) => {
			$scope.data.refTypes = _.map(refTypes,(item) => {
				item.id = item.refType + item.parameterId;
				return item;
			});
			$scope.data.refType = refTypes[0];
		});

		$scope.toggleChecks = (id) => {
			var idx = $scope.data.checked.indexOf(id);
			if (idx > -1) {
				$scope.data.checked.splice(idx, 1);
			}
			else {
				$scope.data.checked.push(id);
			}
		}

		$scope.add = () => {
			$scope.edit({ name: "", shortName: "" });
		};

		$scope.edit = (refItem) => {
			let modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/school/refbook/edit/template.html",
				controller: "EditRefItemCtrl",
				resolve: {
					refType: () => $scope.data.refType,
					refItem: () => angular.copy(refItem)
				}
			}); 
			modalInstance.result.then($scope.load);
		};

		//todo. обработку чекбокса

		$scope.delete = () => {
			$.show.confirmation(language.Generic.Common.kMsgAreYouSure)
				.then(() => {
					refBookRepository.deleteRefItems($scope.data.refType.refType, $scope.data.checked).then(() => {
						$scope.load();
					});
				});
		};

		//загрузка данных
		$scope.load = () => {
			$scope.state.dataReady = false;

			refBookRepository
				.getRefItems($scope.data.refType.refType, $scope.data.refType.parameterId)
				.then((refItems) => {
					$scope.data.checked = [];
					$appLoader.hide();
					$scope.data.refItems = refItems;
					$scope.state.dataReady = true;
					$scope.state.emptyData = $scope.data.refItems.length === 0;
				});
		}

		typesReady.then(() => {
			$scope.load();
		});
	});



